package main

import (
	"fmt"
	"iter"
)

func nums() iter.Seq[int] {
	return func(yield func(int) bool) {
		for i := 1; i <= 3; i++ {
			if !yield(i) {
				return
			}
		}
	}
}

func main() {
	for v := range nums() {
		fmt.Println(v)
	}
}

