package main

import "fmt"

// 使用方定义接口
type Notifier interface {
	Notify(msg string)
}

// 实现方隐式实现 Notifier
type LogNotifier struct{}

func (LogNotifier) Notify(msg string) {
	fmt.Println("[通知]", msg)
}

var _ Notifier = (*LogNotifier)(nil) // 编译期检查

func send(n Notifier, msg string) {
	n.Notify(msg)
}

func main() {
	send(LogNotifier{}, "订单已创建")

	var v any = "键盘"
	if s, ok := v.(string); ok { // 类型断言
		fmt.Println("名称", s)
	}

	switch x := v.(type) { // 类型 switch
	case int:
		fmt.Println("整数", x)
	case string:
		fmt.Println("字符串", x)
	default:
		fmt.Printf("其它 %T\n", x)
	}

	var p *int
	var e any = p
	fmt.Println("接口是 nil 吗？", e == nil) // false
}
